package vn.studylock;
import java.util.*;
/** Original practice items; term grouping is an approximate study plan, not a textbook reproduction. */
public final class Curriculum {
    private final Random r; private String last="";
    public Curriculum(Random random){r=random;}
    private int n(int a,int b){return a+r.nextInt(b-a+1);}
    private Questions.Q q(String s,String p,String a,String... wrong){List<String> c=new ArrayList<>();c.add(a);Collections.addAll(c,wrong);if(new HashSet<>(c).size()!=4)throw new IllegalArgumentException(p);Collections.shuffle(c,r);return new Questions.Q(s,p,a,c);}
    private Questions.Q num(String p,int a){int d=n(1,9);return q("Toán",p,""+a,""+(a+d),""+(a-d),""+(a+2*d));}
    private static String dec(int a){return java.math.BigDecimal.valueOf(a,1).toPlainString().replace('.',',');}
    private Questions.Q decimal(String p,int a){return q("Toán",p,dec(a),dec(a+1),dec(a-1),dec(a+10));}
    private static int gcd(int a,int b){while(b!=0){int t=a%b;a=b;b=t;}return Math.abs(a);}
    private static String frac(int a,int b){int g=gcd(a,b);return b/g==1?""+a/g:(a/g)+"/"+(b/g);}
    private Questions.Q fraction(String p,int a,int b){return q("Toán",p,frac(a,b),frac(a+1,b),frac(a+2,b),frac(a+3,b));}
    private Questions.Q math(int grade,int term,int level){int a=n(2,level*15+5),b=n(2,level*10+4),c=n(2,level*5+3);int k=n(0,5);
        if(grade==4&&term==1){switch(k){case 0:return num((a*1000+31)+" + "+(b*100+12)+" = ?",a*1000+b*100+43);case 1:return num((a*b*100)+" : "+b+" = ?",a*100);case 2:return num(a*13+" × "+b+" = ?",a*13*b);case 3:return num("Hình chữ nhật dài "+a+" cm, rộng "+b+" cm. Chu vi (cm)?",2*(a+b));case 4:return num("Có "+a+" hộp, mỗi hộp "+b+" bút. Thêm "+c+" bút. Tổng số bút?",a*b+c);default:return num(a+" kg bằng bao nhiêu g?",a*1000);}}
        if(grade==4){switch(k){case 0:return fraction("Tính "+a+"/"+b+" + "+c+"/"+b+" (rút gọn).",a+c,b);case 1:return fraction("Tính "+a+"/"+b+" × "+c+" (rút gọn).",a*c,b);case 2:return num("Tìm 1/"+b+" của "+a*b+".",a);case 3:return num("Diện tích hình chữ nhật dài "+a+" cm, rộng "+b+" cm (cm²)?",a*b);case 4:return num("Ba ngày đọc "+a+", "+b+", "+c+" trang. Tổng số trang?",a+b+c);default:return fraction("Rút gọn phân số "+a*c+"/"+b*c+" (rút gọn).",a,b);}}
        if(grade==5&&term==1){switch(k){case 0:return decimal(dec(a)+" + "+dec(b)+" = ?",a+b);case 1:return decimal(dec(a*b)+" : "+b+" = ?",a);case 2:return decimal(dec(a)+" × "+b+" = ?",a*b);case 3:return num(dec(a)+" m bằng bao nhiêu cm?",a*10);case 4:return fraction("Tính "+a+"/"+b+" + "+c+"/"+b+" (rút gọn).",a+c,b);default:return num("Tam giác đáy "+(2*a)+" cm, cao "+b+" cm. Diện tích (cm²)?",a*b);}}
        if(grade==5){switch(k){case 0:return num("Tìm "+(5*c)+"% của "+(20*a)+".",c*a);case 1:return num("Hình hộp dài "+a+", rộng "+b+", cao "+c+" cm. Thể tích (cm³)?",a*b*c);case 2:return num("Đi "+a*b+" km trong "+b+" giờ. Vận tốc (km/h)?",a);case 3:return num("Xe đi với vận tốc "+a+" km/h trong "+b+" giờ, rồi thêm "+c+" km. Tổng quãng đường (km)?",a*b+c);case 4:return num("Hình thang có hai đáy "+(2*a)+", "+(2*b)+" cm, cao "+c+" cm. Diện tích (cm²)?",(a+b)*c);default:return num("Một hộp có "+(a*20)+" viên bi, lấy ra 25%. Còn bao nhiêu viên?",a*15);}}
        if(grade==6&&term==1){switch(k){case 0:return num("("+(-a)+") + "+b+" = ?",b-a);case 1:return num("("+(-a)+") × "+b+" = ?",-a*b);case 2:return num("Ước chung lớn nhất của "+a+" và "+b+"?",gcd(a,b));case 3:return num("Bội chung nhỏ nhất của "+a+" và "+b+"?",a/gcd(a,b)*b);case 4:return num("2 × ("+a+" + "+b+") − "+c+" = ?",2*(a+b)-c);default:return num("Hình vuông cạnh "+a+" cm. Diện tích (cm²)?",a*a);}}
        switch(k){case 0:return fraction("Tính "+a+"/"+b+" − "+c+"/"+b+" (rút gọn).",a-c,b);case 1:return fraction("Tính "+a+"/"+b+" × "+c+"/"+a+" (rút gọn).",a*c,b*a);case 2:return decimal(dec(a)+" × "+b+" = ?",a*b);case 3:return num("Tìm x: x + "+a+" = "+(a+b)+".",b);case 4:return num("Hai góc kề bù, góc thứ nhất "+(a+30)+"°. Góc thứ hai (độ)?",150-a);default:return fraction("Gieo xúc xắc công bằng 6 mặt. Xác suất ra mặt có số chấm không lớn hơn "+(c%5+1)+" (rút gọn)?",c%5+1,6);}
    }
    // grade|term|difficulty. Each group has three independent prompts.
    private static final String[][][] EN={
      {{"Good morning! – ___.|Good morning|Good night|Goodbye yesterday|Tuesday","What day comes after Monday?|Tuesday|Sunday|Friday|Saturday","I ___ from Viet Nam.|am|is|are|be"},{"She ___ a new school bag.|has|have|having|to have","Can you swim? – Yes, I ___.|can|am|do|have","My birthday is ___ June.|in|on|at|of"},{"What time ___ you get up?|do|does|is|are","He ___ breakfast at seven every day.|has|have|having|is have","Choose the correct question about school location.|Where is your school?|Where your school is?|Where are your school?|Where school your?"}},
      {{"Which word means 'bệnh viện'?|hospital|library|school|market","What is the opposite of 'hot'?|cold|old|new|long","There ___ a park near my house.|is|are|am|be"},{"Where is the book? It is ___ the desk, not below it.|on|under|into|between","What ___ the weather like today?|is|are|am|be","How much ___ this T-shirt?|is|are|am|be"},{"We ___ at the zoo yesterday.|were|are|is|am","Why do you like rabbits? – ___ they are cute.|Because|But|Or|When","Choose the correct sentence about a job.|My mother is a nurse.|My mother are a nurse.|My mother a nurse is.|My mother be nurse."}},
      {{"What is the opposite of 'quiet'?|noisy|small|slow|short","Which word means 'thư viện'?|library|factory|market|station","I live ___ Ha Noi.|in|on|at|of"},{"She usually ___ to school by bike.|goes|go|going|to go","What do you like ___ in your free time?|doing|do|does|did","My brother wants ___ a doctor.|to be|be|is|been"},{"They ___ their grandparents yesterday.|visited|visit|visits|visiting","How often do you play chess?|Twice a week|Two metres|At school yesterday|Five books","Choose the correct sentence about an action happening now.|He is reading a book now.|He reading a book now.|He are reading a book now.|He reads a book yesterday."}},
      {{"Which word means 'đau răng'?|toothache|headache|fever|cough","A person who flies a plane is a ___.|pilot|dentist|farmer|cook","You should ___ water when thirsty.|drink|eat|wear|read"},{"I have a fever. I should ___ at home.|rest|rests|resting|rested","The museum is next ___ the bank.|to|at|of|from","How ___ milk do you need?|much|many|old|long"},{"Why shouldn't you play with matches? – Because you may ___.|get burned|get a book|see a movie|learn English","How can I get to the post office? – ___.|Go straight ahead.|I am ten.|It is sunny.|I like milk.","Which is correct?|I'd like some rice, please.|I'd like any rice, please yesterday.|I'd likes some rice.|I like to some rice."}},
      {{"There ___ two bedrooms in my house.|are|is|am|be","Which word means 'môn lịch sử'?|history|maths|music|art","The cat is ___ the chair, below it.|under|above|on|over"},{"My sister ___ English every day.|studies|study|studying|is study","Listen! Someone ___ at the door.|is knocking|knock|knocks yesterday|knocked tomorrow","This street is ___ than that street.|wider|widest|wide|more wide"},{"You ___ litter in the classroom.|mustn't|are|were|has","There isn't ___ water in the bottle.|any|many|a|an","Choose the correct sentence showing possession.|Nam's room is tidy.|Nams room are tidy.|Nam room tidy.|Nams' room am tidy."}},
      {{"Which word means 'môi trường'?|environment|equipment|entertainment|agreement","The opposite of 'win' is ___.|lose|play|run|jump","We ___ a film last night.|watched|watch|watching|watches"},{"He didn't ___ to school yesterday.|go|went|goes|going","This is my pen. It is ___.|mine|my|me|I","I think it ___ rain tomorrow.|will|did|was|has yesterday"},{"If we recycle paper, we ___ save trees.|will|did|were|has","I like this programme ___ it is funny.|because|but|or|although","Choose the correct question about last night.|What did you watch last night?|What do you watched last night?|What did you watched last night?|What you watch last night?"}}
    };
    private static final String[][] EXTRA={
      {"Which word means 'tháng ba'?|March|May|June|July","How old are you? – ___.|I'm nine.|I'm fine.|It's nine.|It's blue."},
      {"I have English ___ Tuesdays.|on|in|at|from","What subjects do you like? – I like ___.|maths|running yesterday|at seven|Monday"},
      {"___ does your school have? – It has two playgrounds.|What|Who|When|Why","She ___ like playing chess.|doesn't|don't|isn't|aren't"},
      {"Which word means 'áo khoác'?|jacket|skirt|sock|shoe","A tiger is an ___.|animal|fruit|school|drink"},
      {"What ___ your father do? – He's a farmer.|does|do|is|are","How many ___ are in the zoo?|monkeys|monkey|a monkey|monkey's"},
      {"Were you at home last Sunday? – Yes, I ___.|was|were|am|is","Choose the correct question about Sunday routines.|What do you do on Sundays?|What does you do on Sundays?|What you do on Sundays?|What do you does on Sundays?"},
      {"Which word means 'sở thích'?|hobby|hospital|holiday|history","I live in a small ___.|village|pencil|shirt|banana"},
      {"My favourite hobby is ___ books.|reading|reads|read yesterday|to reads","He ___ his teeth twice a day.|brushes|brush|brushing|is brush"},
      {"What did you see at the zoo? – I ___ some tigers.|saw|see|sees|seeing","Choose the correct question about a future job.|What would you like to be?|What would you like be?|What you would like to be?|What would you likes to be?"},
      {"Which word means 'nhà ga'?|station|hospital|school|garden","A person who takes care of sick people is a ___.|doctor|pilot|driver|farmer"},
      {"You shouldn't ___ your hands on a hot stove.|put|puts|putting|to put","I need ___ medicine for my headache.|some|many|a few|an"},
      {"Excuse me, ___ is the nearest bus stop?|where|who|how many|why not","What should I do if I have a toothache? – You should ___.|see a dentist|eat more sweets|drink less water|touch a hot stove"},
      {"Which word means 'tủ lạnh'?|fridge|wardrobe|desk|sofa","My brother and I ___ students.|are|is|am|be"},
      {"This is ___ ruler, not mine.|her|hers|she|he's","The library is ___ the bank and the school.|between|under|on|into"},
      {"We haven't got ___ apples left.|any|much|a|an","You should ___ your room before Tet.|clean|cleans|cleaning|to clean"},
      {"Which word means 'trận đấu'?|match|map|meal|month","The past form of 'run' is ___.|ran|runned|runs|running"},
      {"Don't ___ rubbish in the park.|drop|drops|dropped|dropping","That bicycle is ___. It belongs to them.|theirs|their|they|them"},
      {"If you turn off the lights, you ___ save energy.|will|did|were|has","I wanted to watch TV, ___ I had homework to finish.|but|because|so that|when"}
    };
    private Questions.Q english(int g,int term,int level){String[] group=EN[(g-4)*2+term-1][level-1];String[] extra=EXTRA[((g-4)*2+term-1)*3+level-1];int pick=n(0,group.length+extra.length-1);String[] x=(pick<group.length?group[pick]:extra[pick-group.length]).split("\\|");return q("Tiếng Anh",x[0],x[1],x[2],x[3],x[4]);}
    public Questions.Q next(int grade,int term,String subject,int level){Questions.Q x;int tries=0;do{int t=term==0?n(1,2):term;x=subject.equals("math")?math(grade,t,level):english(grade,t,level);}while(x.prompt.equals(last)&&++tries<30);last=x.prompt;return x;}
    public static int englishCount(){int count=0;for(String[][] a:EN)for(String[] b:a)count+=b.length;for(String[] a:EXTRA)count+=a.length;return count;}
}
